import pathlib,json,math,shapely
from shapely.geometry import Polygon,LineString,mapping,box
from shapely.ops import transform,split,unary_union,polylabel
P=pathlib.Path(__file__).parent/'120';d=json.loads((P/'source-data.json').read_text());old=json.loads((P/'regions.json').read_text());poly=Polygon(d['ring_m']);theta=d['facade_axis_rad_inferred'];co,si=math.cos(theta),math.sin(theta);pu=transform(lambda x,y:(x*co+y*si,-x*si+y*co),poly);lo,hi=pu.bounds[1],pu.bounds[3];cut=lo+(hi-lo)*.42;line=LineString([(u*co-cut*si,u*si+cut*co) for u in [-1000,1000]]);pieces=list(split(poly,line).geoms);lower=unary_union([q for q in pieces if -q.representative_point().x*si+q.representative_point().y*co<cut]);upper=unary_union([q for q in pieces if -q.representative_point().x*si+q.representative_point().y*co>=cut]);assert lower.intersection(upper).area<1e-8 and unary_union([lower,upper]).symmetric_difference(poly).area<1e-8
for region,q in zip(old,[lower,upper]):
 parts=list(q.geoms) if hasattr(q,'geoms') else [q];region['geometry']=mapping(q);region['polygons']=[{'ring':list(part.exterior.coords)[:-1],'triangles':[list(tr.exterior.coords)[:3] for tr in shapely.constrained_delaunay_triangles(part).geoms]} for part in parts];uv=transform(lambda x,y:(x*co+y*si,-x*si+y*co),q);parts=list(uv.geoms) if hasattr(uv,'geoms') else [uv];largest=max(parts,key=lambda q:q.area);c=polylabel(largest,tolerance=.01);radius=c.distance(largest.boundary);w=min(8,radius);h=min(4,radius);assert uv.covers(box(c.x-w/2-.25,c.y-h/2-.25,c.x+w/2+.25,c.y+h/2+.25));region['roof_frame_uv']=[c.x,c.y,w,h]
(P/'regions.json').write_text(json.dumps(old,indent=2));print('120 exact partition fixed',lower.area,upper.area)
